-- C3 Site Finder: step 2, schema c3 and its 18 tables (generated by "NJTruckCharging.CloudCopy script"; run by "create-schema" as c3_migrator).
DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'c3') THEN
