    "BusinessesOnSite" character varying(1000),
    "BusinessCategories" character varying(1000),
    "BusinessPhone" character varying(50),
    "BusinessWebsite" text,
    "FreightUse" boolean NOT NULL,
    "IndustrialUse" boolean NOT NULL,
    "DemandSummary" character varying(1000),
    "TrucksBased3Mi" integer NOT NULL,
    "TrucksBased5Mi" integer NOT NULL,
    "TrucksBased10Mi" integer NOT NULL,
    "CarriersBased5Mi" integer NOT NULL,
    "TractorsBased5Mi" integer NOT NULL,
    "TruckAadtAdjacent" integer NOT NULL,
    "TruckAadtAtExit" integer NOT NULL,
    "MilesToTruckRoad" double precision NOT NULL,
    "LargeWarehouses2Mi" integer NOT NULL,
    "TruckStops2Mi" integer NOT NULL,
    "MilesToTruckStop" double precision NOT NULL,
    "MilesToPort" double precision NOT NULL,
    "NearestPort" character varying(100),
    "NearestHighway" character varying(100),
