    "InFloodZone" boolean NOT NULL,
    "InHighlandsPreservation" boolean NOT NULL,
    "IsContaminated" boolean NOT NULL,
    "NearPowerEdisonSite" boolean NOT NULL,
    "Breakdown_ExitDistance" double precision NOT NULL,
    "Breakdown_OpenLand" double precision NOT NULL,
    "Breakdown_PropertyClass" double precision NOT NULL,
    "Breakdown_TruckingOnSite" double precision NOT NULL,
    "Breakdown_FleetsNearby" double precision NOT NULL,
    "Breakdown_TruckTraffic" double precision NOT NULL,
    "Breakdown_LargeWarehouses" double precision NOT NULL,
    "Breakdown_TruckStop" double precision NOT NULL,
    "Breakdown_Port" double precision NOT NULL,
    "Breakdown_NoTruckCharger" double precision NOT NULL,
    "Breakdown_NoFastCharger" double precision NOT NULL,
    "Breakdown_LotShape" double precision NOT NULL,
    "Breakdown_FarFromTruckRoad" double precision NOT NULL,
    "Breakdown_Highlands" double precision NOT NULL,
    "Breakdown_BusyMultiTenant" double precision NOT NULL,
    "Breakdown_Flood" double precision NOT NULL,
