    "UpdatedAtUtc" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_CustomDataFields" PRIMARY KEY ("Id"),
    CONSTRAINT "AK_CustomDataFields_Key" UNIQUE ("Key")
);


CREATE TABLE c3."FeasibilityItems" (
